class Solution:
    def maxKDivisibleComponents(self, n: int, edges: List[List[int]], values: List[int], k: int) -> int:
        G = defaultdict(list)

        for u, v in edges:
            G[u].append(v)
            G[v].append(u)

        components = 0
        visited = [False] * n

        def dfs(v):
            nonlocal components
            visited[v] = True
            res = values[v]
            for w in G[v]:
                if not visited[w]:
                    cur = dfs(w)
                    res += cur
                    if cur % k == 0:
                        components += 1
            return res

        for i in range(n):
            if not visited[i]:
                total = dfs(i)
                if total % k == 0:
                    components += 1

        return components

