class Solution:
    def minEdgeReversals(self, n: int, edges: List[List[int]]) -> List[int]:
        g = defaultdict(list)
        ans = [0] * n

        for u, v in edges:
            g[u].append((v, 1))  # original direction
            g[v].append((u, 0))  # reversed direction

        def bfs(start):
            queue = deque([(start, 0)])  # (node, count of reversals)
            visited = set()
            visited.add(start)
            total_reversals = 0

            while queue:
                par, parCnt = queue.popleft()
                ans[par] = parCnt

                for child, cnt in g[par]:
                    if child not in visited:
                        visited.add(child)
                        total_reversals += cnt
                        queue.append((child, parCnt + cnt))

        bfs(0)

        for i in range(n):
            ans[i] += (n - 1 - sum(ans)) // 2

        return ans

