class Solution:
    def findMaximumElegance(self, items: List[List[int]], k: int) -> int:
        if k > len(items):
            return 0

        items.sort(reverse=True, key=lambda x: x[0])

        sm = 0
        seenCats = set()
        dups = deque()

        for i in range(k):
            headPrf, headCat = items[i]
            sm += headPrf
            if headCat in seenCats:
                dups.append(headPrf)
            else:
                seenCats.add(headCat)

        numCats = len(seenCats)
        ans = sm + numCats ** 2

        for i in range(k, len(items)):
            tailPrf, tailCat = items[i]
            if tailCat in seenCats:
                continue

            if dups:
                leastProfitable = dups.popleft()
                sm += tailPrf - leastProfitable
            else:
                sm += tailPrf

            seenCats.add(tailCat)
            numCats = len(seenCats)
            ans = max(ans, sm + numCats ** 2)

        return ans

